2	import { SupabaseService } from '../supabase/supabase.service';
3	import { haversineKm } from '../common/geo.util';
4	import * as os from 'os';
5	
6	const PRODUTO_FIELDS = 'id, name, description, price, preco_promo, image_url, category_id, restaurant_id, tags, destaque, is_active';
