8	@Controller('r')
9	export class CatalogoController {
10	  constructor(private supabase: SupabaseService) {}
11	
12	  @Get('acesso')
13	  async getAcesso() {
14	    const nets = os.networkInterfaces();
15	    const todos: string[] = [];
16	    for (const iface of Object.values(nets)) {
17	      for (const net of iface ?? []) {
18	        if (net.family === 'IPv4' && !net.internal) todos.push(net.address);
